#include <stddef.h>

long long transform(const long long *xs, size_t len, long long lo, long long hi) {
    long long s = 0;
    for (size_t i = 0; i < len; i++) {
        long long x = xs[i] % 2 ? xs[i] * 2 : xs[i];
        if (x < lo)
            x = lo;
        if (x > hi)
            x = hi;
        s += x;
    }
    return s;
}

#include <assert.h>
#include "transform.c"

int main(void) {
    assert(transform((long long[]){1, 2, 3, -4}, 4, 0, 5) == 9);
    assert(transform(NULL, 0, 0, 1) == 0);
    return 0;
}
